<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/auth.php';require_once __DIR__.'/../config/helpers.php';require_admin();$rows=$pdo->query("SELECT p.*,COALESCE(c.name,'General') category_name FROM products p LEFT JOIN categories c ON c.category_id=p.category_id WHERE p.status='ACTIVE' ORDER BY p.quantity_in_stock ASC")->fetchAll();$tx=$pdo->query("SELECT t.transaction_id,t.created_at,t.transaction_type,t.quantity,p.product_name,COALESCE(u.username,'Customer Order') actor FROM transactions t JOIN products p ON p.product_id=t.product_id LEFT JOIN users u ON u.user_id=t.user_id ORDER BY t.transaction_id DESC LIMIT 80")->fetchAll();$title='Inventory Control';require __DIR__.'/../includes/header.php';?><section class="shell admin-page"><div class="admin-top"><div><span class="eyebrow">STOCK CONTROL</span><h1>Inventory</h1><p>Monitor stock, reorder levels and every recent movement.</p></div><a class="btn btn-primary" href="/admin/products.php">Manage products</a></div><div class="panel"><div class="table-wrap"><table class="pro-table"><tr><th>Product</th><th>Category</th><th>Stock</th><th>Reorder</th><th>Unit price</th><th>Inventory value</th></tr><?php foreach($rows as $r):?><tr><td><strong><?=e($r['product_name'])?></strong><small><?=e($r['sku_code'])?></small></td><td><?=e($r['category_name'])?></td><td class="<?=((int)$r['quantity_in_stock']<=(int)$r['reorder_level']?'danger-text':'')?>"><?=$r['quantity_in_stock']?></td><td><?=$r['reorder_level']?></td><td><?=money($r['unit_price'])?></td><td><?=money($r['quantity_in_stock']*$r['unit_price'])?></td></tr><?php endforeach;?></table></div></div><div class="panel"><div class="panel-title"><h2>Recent stock movements</h2></div><div class="table-wrap"><table class="pro-table"><tr><th>Date</th><th>Product</th><th>Type</th><th>Qty</th><th>Actor</th></tr><?php foreach($tx as $t):?><tr><td><?=e($t['created_at'])?></td><td><?=e($t['product_name'])?></td><td><span class="status-pill <?=($t['transaction_type']==='IN'?'ok':'off')?>"><?=e($t['transaction_type'])?></span></td><td><?=$t['quantity']?></td><td><?=e($t['actor'])?></td></tr><?php endforeach;?></table></div></div></section><?php require __DIR__.'/../includes/footer.php';?>